import {
  Object3D,
  Mesh,
  PlaneGeometry,
  Color,
} from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @param {Object} config - Node configuration
 * @param {Object} ctx - Runtime context (provides textureLoader, emit, etc.)
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // ---- Extract configuration -------------------------------------------------
  const {
    assets: { imageUrl },
    colors = {},
    position = [0, 0, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
  } = config;

  // ---- Load texture -----------------------------------------------------------
  const texture = ctx.textureLoader(imageUrl);
  texture.encoding = ctx.renderer?.outputEncoding ?? texture.encoding;

  // ---- Create material ---------------------------------------------------------
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: new Color(colors.paper ?? '#e8ecf2'),
    transparent: true,
  });

  // ---- Plane geometry ---------------------------------------------------------
  const geometry = new PlaneGeometry(1, 0.4); // capsule‑like aspect ratio
  const plane = new Mesh(geometry, material);
  plane.scale.set(1, 1, 1);
  plane.rotation.set(0, 0, 0);
  plane.position.set(0, 0, 0);

  // ---- Assemble root object ---------------------------------------------------
  const root = new Object3D();
  root.position.fromArray(position);
  root.rotation.fromArray(rotation);
  root.scale.fromArray(scale);
  root.add(plane);

  // ---- Interaction state -------------------------------------------------------
  const baseY = root.position.y;
  let hoverTween = null;

  const onHoverEnter = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(root.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverLeave = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(root.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onClick = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-collection.select');
    } else if (ctx.events && typeof ctx.events.emit === 'function') {
      ctx.events.emit('hub-collection.select');
    }
  };

  // ---- Attach handlers ---------------------------------------------------------
  root.userData.handlers = {
    pointerenter: onHoverEnter,
    pointerleave: onHoverLeave,
    click: onClick,
  };

  // ---- Cleanup -----------------------------------------------------------------
  root.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    material.dispose();
    if (texture) texture.dispose();
    geometry.dispose();
  };

  return root;
}
